    ee_bhxh numeric(6,5) NOT NULL,
    ee_bhyt numeric(6,5) NOT NULL,
    ee_bhtn numeric(6,5) NOT NULL,
    er_bhxh_pension numeric(6,5) NOT NULL,
    er_bhxh_sickness_maternity numeric(6,5) NOT NULL,
    er_bhxh_accident numeric(6,5) NOT NULL,
    er_bhyt numeric(6,5) NOT NULL,
    er_bhtn numeric(6,5) NOT NULL,
    probation_exempt boolean DEFAULT true NOT NULL,
    created_at timestamp without time zone,
    created_by character varying(100),
    updated_at timestamp without time zone,
    updated_by character varying(100),
    CONSTRAINT chk_ins_ee_bhtn CHECK (((ee_bhtn >= (0)::numeric) AND (ee_bhtn <= (1)::numeric))),
    CONSTRAINT chk_ins_ee_bhxh CHECK (((ee_bhxh >= (0)::numeric) AND (ee_bhxh <= (1)::numeric))),
    CONSTRAINT chk_ins_ee_bhyt CHECK (((ee_bhyt >= (0)::numeric) AND (ee_bhyt <= (1)::numeric))),
    CONSTRAINT chk_ins_er_accident CHECK (((er_bhxh_accident >= (0)::numeric) AND (er_bhxh_accident <= (1)::numeric))),
    CONSTRAINT chk_ins_er_bhtn CHECK (((er_bhtn >= (0)::numeric) AND (er_bhtn <= (1)::numeric))),
    CONSTRAINT chk_ins_er_bhyt CHECK (((er_bhyt >= (0)::numeric) AND (er_bhyt <= (1)::numeric))),
    CONSTRAINT chk_ins_er_pension CHECK (((er_bhxh_pension >= (0)::numeric) AND (er_bhxh_pension <= (1)::numeric))),
    CONSTRAINT chk_ins_er_sickness CHECK (((er_bhxh_sickness_maternity >= (0)::numeric) AND (er_bhxh_sickness_maternity <= (1)::numeric)))
);


