    coefficient double precision DEFAULT 1.5 NOT NULL
);


--
-- Name: ot_monthly_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ot_monthly_summary AS
 SELECT employee_id,
    (EXTRACT(year FROM start_time))::integer AS ot_year,
    (EXTRACT(month FROM start_time))::integer AS ot_month,
    sum((EXTRACT(epoch FROM (end_time - start_time)) / (60)::numeric)) AS approved_minutes
   FROM public.ot_request ot
  WHERE (((status)::text = 'APPROVED'::text) AND (delete_flag = false))
  GROUP BY employee_id, ((EXTRACT(year FROM start_time))::integer), ((EXTRACT(month FROM start_time))::integer);


